import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:suite @smoke Open homepage and contact page in parallel tabs', async ({ page }) => {
  await opGoto(page, '/')
  await opClick(page, 'link', 'Contact')
  await opFill(page, 'Name', 'Tab 1 User')
  await opFill(page, 'Email', 'tab1@example.com')
  await opPress(page, 'Enter')
  await opSeen(page, 'main', 'Contact us')
})
